export async function handler(req,res){try{let url=new URL(req.url,`http://${req.headers.host||'localhost'}`);const rewrittenPath=url.searchParams.get('__path');if(rewrittenPath){url=new URL(rewrittenPath,`http://${req.headers.host||'localhost'}`);for(const[key,value]of new URL(req.url,`http://${req.headers.host||'localhost'}`).searchParams)if(key!=='__path')url.searchParams.append(key,value)}if(url.pathname.startsWith('/api/'))return await api(req,res,url);if(url.pathname==='/checkout')return stream(join(root,'public','checkout.html'),res);if(url.pathname==='/admin'||url.pathname==='/admin/'){return stream(join(root,'public',adminOk(req)?'admin.html':'admin-login.html'),res)}if(url.pathname.startsWith('/assets/'))return stream(join(root,'public',url.pathname.slice(8)),res);const safe=normalize(url.pathname).replace(/^(\.\.[/\\])+/,'');let target=join(root,safe);if(url.pathname==='/')target=join(root,'index.html');else if(existsSync(target)&&statSync(target).isDirectory())target=join(target,'index.html');else if(!extname(target))target=join(root,safe,'index.html');if(!existsSync(target)||!statSync(target).isFile()){res.writeHead(404);return res.end('Not found')}if(extname(target)==='.html'){let html=syncOfferPricing(url.pathname,await readFile(target,'utf8'));html=html.replace(/href=(['"])https:\/\/getwificode\.com\//gi,'href=$1/').replaceAll('https://perpetualincome365.convertri.com/7figure-everwebinar-registration#aff=DigitalAvalon&amp;cam=membersarea','/webinar').replaceAll('https:\\u002F\\u002Fperpetualincome365.convertri.com\\u002F7figure-everwebinar-registration#aff=DigitalAvalon&cam=membersarea','\\u002Fwebinar');if(!html.includes('/assets/tracker.js'))html=html.replace(/<\/body>/i,'<script src="/assets/tracker.js" defer></script></body>');res.writeHead(200,{'content-type':types['.html'],'cache-control':'no-cache'});return res.end(html)}return stream(target,res)}catch(error){console.error(error);return json(res,500,{error:'Server error'})}}

